import{_ as r,I as a,o,c as l,b6 as t,j as d,J as n,w as c}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"Modern AI Image Generation SaaS","description":"","frontmatter":{},"headers":[],"relativePath":"en/stage-2/assignments/modern-landing-page/index.md","filePath":"en/stage-2/assignments/modern-landing-page/index.md"}'),p={name:"en/stage-2/assignments/modern-landing-page/index.md"},h={style:{margin:"32px 0"}};function m(g,e,u,b,f,k){const i=a("StepBar"),s=a("ClientOnly");return o(),l("div",null,[e[0]||(e[0]=t('<h1 id="modern-ai-image-generation-saas" tabindex="-1">Modern AI Image Generation SaaS <a class="header-anchor" href="#modern-ai-image-generation-saas" aria-label="Permalink to “Modern AI Image Generation SaaS”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>This project requires you to build a Midjourney-inspired AI image generation SaaS product from scratch, based on a real PRD. You&#39;ll go through the full process: requirements analysis, project breakdown, iterative development, and integration testing.</p><p>This is the comprehensive practical section of Stage 2. In previous chapters, you&#39;ve learned individual skills — frontend design, backend APIs, databases, payment integration. This project ties them all together into a runnable product prototype.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>Before starting this project, you should already be familiar with:</p><ul><li>Frontend page design and component libraries (<a href="./../../frontend/ui-design/">UI Design</a>, <a href="./../../frontend/modern-component-library/">Modern Component Libraries</a>)</li><li>Backend API design and development (<a href="./../../backend/ai-interface-code/">API Code</a>)</li><li>Database fundamentals and Supabase (<a href="./../../backend/database-supabase/">Database to Supabase</a>)</li><li>Payment integration (<a href="./../../backend/stripe-payment/">Stripe Payment System</a>)</li><li>Git workflow and deployment (<a href="./../../backend/git-workflow/">Git &amp; GitHub</a>, <a href="./../../backend/zeabur-deployment/">Web App Deployment</a>)</li></ul><h2 id="learning-objectives" tabindex="-1">Learning Objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to “Learning Objectives”">​</a></h2><p>After completing this project, you will be able to:</p><ol><li>Read and understand a real PRD, extracting a development task list</li><li>Break down modules based on the PRD and create a step-by-step plan</li><li>Use AI assistance to build frontend scaffolds and backend APIs</li><li>Verify and iterate on each module</li><li>Complete end-to-end integration, taking the project from &quot;runs locally&quot; to &quot;deliverable&quot;</li></ol><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to “Project Overview”">​</a></h2><p>You will build a modern AI image generation SaaS platform with three subsystems:</p><table tabindex="0"><thead><tr><th>Subsystem</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>Public Website</strong></td><td>Product intro, pricing, FAQ, registration conversion</td></tr><tr><td><strong>User Workspace</strong></td><td>Prompt input, image generation, gallery, credits, plans, community interaction</td></tr><tr><td><strong>Admin Dashboard</strong></td><td>User management, task management, payment management, content moderation, SaaS metrics, system monitoring</td></tr></tbody></table><p>The backend needs to support: user auth, image generation tasks, OSS object storage, credits and plan payments, image social interaction, and operations data monitoring.</p><div class="tip custom-block"><p class="custom-block-title">PRD</p><p>The requirements document for this project is on GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/en/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">View PRD</a></p></div>',15)),d("div",h,[n(s,null,{default:c(()=>[n(i,{active:0,items:[{title:"Requirements",description:"Read PRD, extract pages, modules, data models, and scope"},{title:"Scaffold",description:"Use AI to generate three frontend skeletons (www / app / admin)"},{title:"Iterate",description:"Add APIs, auth, payments, monitoring module by module"},{title:"Launch",description:"End-to-end testing, deploy, and prepare demo"}]})]),_:1})]),e[1]||(e[1]=t(`<h2 id="part-1-requirements-analysis" tabindex="-1">Part 1: Requirements Analysis <a class="header-anchor" href="#part-1-requirements-analysis" aria-label="Permalink to “Part 1: Requirements Analysis”">​</a></h2><h3 id="_1-1-read-the-prd" tabindex="-1">1.1 Read the PRD <a class="header-anchor" href="#_1-1-read-the-prd" aria-label="Permalink to “1.1 Read the PRD”">​</a></h3><p>Open the PRD document and answer these key questions:</p><ul><li>How many entry points does the system have? Which pages does each cover?</li><li>What is the core functionality of each page?</li><li>What modules and database tables does the backend include?</li><li>What is the MVP scope? What goes in the first version and what doesn&#39;t?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>If the above questions don&#39;t have clear answers, don&#39;t start coding. Unclear requirements are the most common cause of rework.</p></div><h3 id="_1-2-confirm-system-architecture" tabindex="-1">1.2 Confirm System Architecture <a class="header-anchor" href="#_1-2-confirm-system-architecture" aria-label="Permalink to “1.2 Confirm System Architecture”">​</a></h3><p>Map out the overall architecture based on the PRD:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;Public Website&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;User Workspace&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;Admin Dashboard&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;Auth&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;Image Generation Task&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;OSS Storage&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;Database&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;Payments &amp; Plans&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;Share / Like / Comment / Repost&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;SaaS Metrics Dashboard&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;API / DB / Provider Monitoring&quot;]</span></span></code></pre></div><p>We recommend drawing the architecture diagram in your own words to confirm your understanding is complete.</p><h2 id="part-2-project-scaffolding" tabindex="-1">Part 2: Project Scaffolding <a class="header-anchor" href="#part-2-project-scaffolding" aria-label="Permalink to “Part 2: Project Scaffolding”">​</a></h2><h3 id="_2-1-generate-frontend-pages" tabindex="-1">2.1 Generate Frontend Pages <a class="header-anchor" href="#_2-1-generate-frontend-pages" aria-label="Permalink to “2.1 Generate Frontend Pages”">​</a></h3><p>Use AI to generate the basic structure and mock data for all pages. The goal here is to set up the information architecture and routing — no real API integration yet.</p><p>Prompt reference:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Based on the current PRD, help me generate a frontend scaffold for a modern AI image generation SaaS.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>1. Three entry points: www, app, admin</span></span>
<span class="line"><span>2. www: homepage, pricing, FAQ</span></span>
<span class="line"><span>3. app: login, register, generation workspace, gallery, plans, credits, community, artwork detail, profile</span></span>
<span class="line"><span>4. admin: dashboard homepage, user management, task management, content management, plan management, payment orders, operations config, SaaS metrics, system monitoring</span></span>
<span class="line"><span>5. Only generate page structure with mock data, no real API integration</span></span>
<span class="line"><span>6. Style reference: Midjourney — clean, modern, product-like</span></span></code></pre></div><h3 id="_2-2-verify-page-structure" tabindex="-1">2.2 Verify Page Structure <a class="header-anchor" href="#_2-2-verify-page-structure" aria-label="Permalink to “2.2 Verify Page Structure”">​</a></h3><p>After generating the scaffold, check each item:</p><ul><li>[ ] Three entry point routes are independent (<code>/</code>, <code>/app</code>, <code>/admin</code>)</li><li>[ ] Page count matches the PRD</li><li>[ ] Each page is accessible and navigable</li><li>[ ] Mock data shows basic UI states (lists, empty states, forms, etc.)</li></ul><h2 id="part-3-iterative-development" tabindex="-1">Part 3: Iterative Development <a class="header-anchor" href="#part-3-iterative-development" aria-label="Permalink to “Part 3: Iterative Development”">​</a></h2><h3 id="_3-1-module-by-module-progress" tabindex="-1">3.1 Module-by-Module Progress <a class="header-anchor" href="#_3-1-module-by-module-progress" aria-label="Permalink to “3.1 Module-by-Module Progress”">​</a></h3><p>On top of the scaffold, add features module by module in this order:</p><ol><li><strong>Authentication</strong>: Registration, login, role differentiation</li><li><strong>Database</strong>: Table creation, read/write APIs</li><li><strong>Core Business</strong>: Image generation tasks, result storage</li><li><strong>OSS Storage</strong>: Image upload and access</li><li><strong>Payments</strong>: Plans, credits, Stripe integration</li><li><strong>Social Interaction</strong>: Sharing, likes, comments</li><li><strong>Admin Dashboard</strong>: User management, task management, content moderation</li><li><strong>Data Monitoring</strong>: SaaS metrics dashboard, system monitoring</li></ol><p>After each module, use this self-check table:</p><table tabindex="0"><thead><tr><th>Check Item</th><th>Verification Method</th></tr></thead><tbody><tr><td>Page consistency</td><td>Do page count, entry points, and features match the PRD?</td></tr><tr><td>API correctness</td><td>Are request params, response structure, and status handling reasonable?</td></tr><tr><td>Auth isolation</td><td>Are regular users and admins properly separated?</td></tr><tr><td>Data consistency</td><td>Do database, OSS, payment, and credits data align?</td></tr><tr><td>Demo readiness</td><td>Can you demo a complete business flow to someone else?</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>If AI-generated content drifts from the PRD, don&#39;t throw away the whole page — just ask it to fix the specific module.</p></div><h3 id="_3-2-roles-responsibilities" tabindex="-1">3.2 Roles &amp; Responsibilities <a class="header-anchor" href="#_3-2-roles-responsibilities" aria-label="Permalink to “3.2 Roles &amp; Responsibilities”">​</a></h3><p>During iteration, you need to play three roles simultaneously:</p><ul><li><strong>Product Manager</strong>: Confirm each module&#39;s features match the PRD</li><li><strong>Tech Lead</strong>: Confirm the implementation approach is reasonable</li><li><strong>QA Engineer</strong>: Confirm the features actually work</li></ul><h2 id="part-4-integration-launch" tabindex="-1">Part 4: Integration &amp; Launch <a class="header-anchor" href="#part-4-integration-launch" aria-label="Permalink to “Part 4: Integration &amp; Launch”">​</a></h2><h3 id="_4-1-end-to-end-testing" tabindex="-1">4.1 End-to-End Testing <a class="header-anchor" href="#_4-1-end-to-end-testing" aria-label="Permalink to “4.1 End-to-End Testing”">​</a></h3><p>The focus at this stage is not adding new pages but running complete business flows. At minimum, verify:</p><ul><li>Register → Buy credits → Generate image → View history → Share and interact</li><li>Admin login → View user data → View task statistics → View system monitoring</li></ul><h3 id="_4-2-deployment" tabindex="-1">4.2 Deployment <a class="header-anchor" href="#_4-2-deployment" aria-label="Permalink to “4.2 Deployment”">​</a></h3><p>Deploy the project to a public environment, ensuring:</p><ul><li>Environment variables are fully configured</li><li>Login callback URLs are correct</li><li>Payment callback URLs are correct</li><li>Pages don&#39;t have missing loading, empty states, or error messages</li></ul><p>For deployment instructions, see: <a href="./../../backend/git-workflow/">Git &amp; GitHub Workflow</a>, <a href="./../../backend/zeabur-deployment/">Web App Deployment</a>.</p><h2 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to “Deliverables”">​</a></h2><p>After completing this project, submit the following:</p><ul><li>[ ] Accessible live demo link</li><li>[ ] Source code repository link (with README)</li><li>[ ] PRD document</li><li>[ ] Core page screenshots (homepage, generation workspace, gallery, plans page, admin dashboard)</li><li>[ ] 60-second demo video (covering register → generate → view → admin management)</li></ul><p>README should include at minimum: project overview, core page descriptions, tech stack, local setup steps, and environment variable list.</p><h2 id="grading-criteria" tabindex="-1">Grading Criteria <a class="header-anchor" href="#grading-criteria" aria-label="Permalink to “Grading Criteria”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Basic Requirements</th><th>Advanced Requirements</th></tr></thead><tbody><tr><td>PRD Alignment</td><td>Pages, features, and data structures basically match PRD</td><td>Can clearly explain each design decision&#39;s PRD correspondence</td></tr><tr><td>Product Loop</td><td>Register → Buy credits → Generate image → View history → Share works end-to-end</td><td>Payment status, credit balance, and generation count data are consistent</td></tr><tr><td>Admin Capability</td><td>Users, tasks, payments, and content management are viewable</td><td>SaaS metrics dashboard and system monitoring page are fully functional</td></tr><tr><td>Engineering Completeness</td><td>Frontend, backend, database, OSS, payment pipeline connected</td><td>Has error handling, empty states, and loading states</td></tr><tr><td>Delivery Quality</td><td>Deployable and runnable</td><td>README is clear, demo video is well-structured</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI Design</a></li><li><a href="./../../frontend/multi-product-ui/">Multi-Product UI Design</a></li><li><a href="./../../frontend/llm-skills-beautiful/">LLM &amp; Skills Interface Beautification</a></li><li><a href="./../../frontend/design-to-code/">Design Prototype to Project Code</a></li><li><a href="./../../frontend/modern-component-library/">Modern Component Libraries</a></li><li><a href="./../../backend/database-supabase/">Database to Supabase</a></li><li><a href="./../../backend/ai-interface-code/">API Code with LLM Assistance</a></li><li><a href="./../../backend/git-workflow/">Git &amp; GitHub Workflow</a></li><li><a href="./../../backend/zeabur-deployment/">Web App Deployment</a></li><li><a href="./../../backend/stripe-payment/">Stripe Payment Integration</a></li></ul>`,43))])}const v=r(p,[["render",m]]);export{P as __pageData,v as default};
